const SESSION = 'pel-review2-session'
const emptyState = { users: [], customers: [], opportunities: [], tasks: [], activity: [], settings: { workspaceName: 'PEL CRM', adminNotifications: true, defaultTaskPriority: 'Medium', adminWelcome: 'Manage users, workload, and assigned CRM records.', userPreferences: {} } }
const ADMIN = { id: 'pel-admin', name: 'S. Eswar Charan', email: 'admin@pel.local', password: 'PELAdmin@2026', role: 'admin', status: 'Active' }
const adminNav = ['Dashboard', 'Customers', 'Pipeline', 'Tasks', 'Users', 'Settings']
const userNav = ['Dashboard', 'Customers', 'Pipeline', 'Tasks', 'My Profile', 'Settings']
const stages = ['New lead', 'Qualified', 'Proposal', 'Negotiation', 'Won', 'Lost']
